    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'No casual or inadvertent failure to comply with any credit obligation, nor any failure by third parties to comply with their credit obligations, shall constitute a breach of this Agreement. Amazon''s sole obligation shall be to prospectively cure any such failure on future copies or broadcasts, to the extent commercially practicable.', ARRAY['casual inadvertent failure','third parties','not breach','sole obligation','prospectively cure','future copies','broadcasts','commercially practicable']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Standard inadvertent failure language", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard protection against credit errors becoming breach claims. Prospective cure only, with commercial practicability qualifier. Industry-standard language."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Any inadvertent failure to accord credit in accordance with this Agreement shall not be a breach hereof, and ProdCo''s sole remedy shall be prospective correction on a going-forward basis when and if such correction is reasonably practicable.', ARRAY['inadvertent failure','not breach','sole remedy','prospective correction','going-forward','reasonably practicable']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Sole remedy limitation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly limits remedy to prospective correction, preventing damages claims for credit errors. ''Sole remedy'' language is important."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall not be in breach of any credit obligation due to any inadvertent omission or error, or any act or omission of third parties including distributors, licensees, broadcasters or exhibitors. Amazon agrees to use reasonable efforts to correct any credit error on prospective copies or broadcasts.', ARRAY['not in breach','inadvertent omission error','third parties','distributors licensees broadcasters exhibitors','reasonable efforts','correct','prospective']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Third party and distributor coverage", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly covers third-party errors (distributors, broadcasters) which are common sources of credit issues and outside Amazon''s direct control."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'No failure to comply with credit provisions, whether inadvertent, casual or otherwise, shall constitute a breach or default under this Agreement. ProdCo waives any claim, cause of action or remedy arising from any credit failure, and agrees that prospective cure shall be the exclusive remedy for any such failure.', ARRAY['failure','inadvertent casual otherwise','not breach default','waives','claim cause of action remedy','prospective cure','exclusive remedy']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Broad waiver with exclusive remedy", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Expands beyond ''inadvertent'' to cover all credit failures, with explicit waiver of claims. Very strong protection for Amazon."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Inadvertent credit failures shall not constitute breach. Amazon shall have no obligation to recall, remaster or re-release any materials to correct credit errors, and prospective correction shall be limited to new production runs or newly-created digital assets.', ARRAY['inadvertent','not breach','no obligation','recall remaster re-release','prospective correction','new production runs','digital assets']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "No recall or remastering obligation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly excludes recall, remastering, or re-release obligations which could be extremely costly. Limits prospective cure to new materials."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Credit errors or omissions, whether by Amazon or any third party, shall not be deemed a breach of this Agreement, and Amazon shall have no liability therefor. Amazon''s sole obligation, upon written notice from ProdCo identifying a specific credit error, shall be to use commercially reasonable efforts to correct such error prospectively.', ARRAY['credit errors omissions','Amazon','third party','not breach','no liability','sole obligation','written notice','commercially reasonable efforts','prospectively']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Notice requirement for cure", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Adds notice requirement, shifting burden to ProdCo to identify errors before cure obligation triggers. Reasonable procedural protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Failure to accord credit as contemplated herein shall not constitute a breach if such failure is inadvertent and is corrected prospectively within a commercially reasonable time after Amazon receives written notice thereof from ProdCo.', ARRAY['failure','not breach','inadvertent','corrected prospectively','commercially reasonable time','written notice']::text[], '{"doc": "PSA_Principal_Terms", "section": "Credit", "note": "Time-based prospective cure", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''Commercially reasonable time'' provides flexibility for cure while still requiring action after notice. Standard acceptable formulation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Inadvertent credit failures shall not be a breach. Amazon shall use best efforts to correct any credit error prospectively within thirty (30) days after receiving written notice from ProdCo.', ARRAY['inadvertent','not breach','best efforts','correct','thirty days','written notice']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Best efforts with 30-day timeline", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "''Best efforts'' is higher standard than ''reasonable efforts.'' 30-day timeline may be acceptable if limited to new materials. Legal should confirm ''best efforts'' is workable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Inadvertent credit failures shall not constitute a breach, and Amazon''s sole obligation shall be prospective cure. If the same credit error occurs on more than three (3) separate occasions after written notice, such repeated failure shall no longer be deemed inadvertent.', ARRAY['inadvertent','not breach','prospective cure','three occasions','written notice','no longer inadvertent']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Repeated failure carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for repeated errors after notice is reasonable as truly inadvertent errors shouldn''t recur. Legal should confirm ''three occasions'' threshold is workable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Credit failures shall not be a breach, and prospective cure shall be the sole remedy; provided that this limitation shall not apply to willful or intentional failure to accord credit that was expressly agreed upon in writing.', ARRAY['not breach','prospective cure','sole remedy','not apply','willful intentional','expressly agreed','writing']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Carveout for willful failures", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for ''willful or intentional'' failure of expressly agreed credits may be reasonable. Legal should assess whether any credits are ''expressly agreed'' under the agreement."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Inadvertent credit failures shall not be a breach, and prospective cure shall be the exclusive remedy. For the avoidance of doubt, this provision shall not limit ProdCo''s right to seek specific performance of credit obligations for future exploitation.', ARRAY['inadvertent','not breach','prospective cure','exclusive remedy','not limit','specific performance','future exploitation']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Specific performance carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Preserving specific performance for future exploitation is consistent with prospective cure concept but uses different legal mechanism. Legal should assess whether this is problematic."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Credit failures shall not constitute breach, and Amazon shall correct prospectively. If any credit failure is not corrected within sixty (60) days after written notice, ProdCo may, at ProdCo''s expense, place a corrective notice on ProdCo''s website regarding the correct credit.', ARRAY['not breach','correct prospectively','sixty days','written notice','ProdCo expense','corrective notice','website']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Self-help corrective notice", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Self-help website notice at ProdCo''s expense is minimal impact and allows ProdCo to address reputational concerns without imposing costs on Amazon. May be acceptable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Inadvertent or casual credit failures by Amazon shall not be a breach, provided that failures caused by Amazon''s licensees or distributors shall not be deemed Amazon''s failure, and Amazon shall have no responsibility for third-party credit errors.', ARRAY['inadvertent casual','not breach','licensees distributors','not Amazon''s failure','no responsibility','third-party errors']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Express third-party disclaimer", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Express disclaimer of responsibility for licensee/distributor errors is protective and consistent with standard position. Legal should confirm this is adequately covered."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Any failure to accord credit as required by this Agreement shall constitute a material breach. ProdCo shall be entitled to damages, injunctive relief and termination of this Agreement for any credit failure, whether inadvertent or otherwise.', ARRAY['failure','material breach','damages','injunctive relief','termination','inadvertent or otherwise']::text[], '{"doc": "Counterparty_Proposal", "section": "Credit", "note": "Credit failure as material breach", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Making all credit failures (including inadvertent) material breach with full remedies is wholly inconsistent with industry standard and operationally unworkable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Inadvertent credit failures shall not be a breach, but Amazon shall pay ProdCo liquidated damages of $10,000 for each credit failure that is not corrected within fifteen (15) days after written notice.', ARRAY['inadvertent','not breach','liquidated damages','$10,000','each failure','fifteen days','written notice']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Liquidated damages for uncured failures", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Liquidated damages for credit failures is inconsistent with prospective-cure-only remedy. Creates significant financial exposure for operational issues."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Credit failures shall not be a breach, but Amazon shall indemnify ProdCo against any reputational harm, loss of business opportunities, or other damages suffered by ProdCo as a result of any credit omission or error.', ARRAY['not breach','indemnify','reputational harm','loss of business','damages','credit omission error']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Indemnity for credit errors", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Indemnification for ''reputational harm'' and ''loss of business opportunities'' from credit errors is speculative, potentially unlimited, and inconsistent with sole-remedy limitation."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Credit failures shall be subject to prospective cure only; provided that Amazon shall recall and replace all physical media and re-issue all digital files to correct any credit error affecting ProdCo''s producer credit.', ARRAY['prospective cure','recall','replace','physical media','re-issue','digital files','producer credit']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Recall and replacement obligation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Recall and replacement obligation for credit errors is extremely costly and impractical. Prospective cure must mean new copies only, not retrofitting existing distribution."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Inadvertent credit failures shall not be a breach, provided that Amazon notifies ProdCo of any credit failure within five (5) business days of Amazon becoming aware of such failure, and corrects the failure within fifteen (15) business days.', ARRAY['inadvertent','not breach','provided','Amazon notifies','five business days','aware','corrects','fifteen business days']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Notice and cure timeline on Amazon", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Imposing notice and cure timelines on Amazon inverts the standard arrangement. Amazon should not have affirmative obligation to discover and report credit errors."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'This inadvertent failure provision shall apply only to credit failures affecting minor contributors. Any failure to accord proper credit to ProdCo, the showrunner, or principal cast members shall constitute a material breach regardless of intent.', ARRAY['inadvertent','minor contributors only','ProdCo','showrunner','principal cast','material breach','regardless of intent']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Carveout for key credits", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Carving out key credits from inadvertent failure protection creates disproportionate exposure for the most visible (and error-prone) credits. Not acceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Inadvertent credit failures shall not be a breach. However, if Amazon fails to correct any credit error within ninety (90) days after notice, ProdCo may terminate this Agreement and retain all rights in the Program.', ARRAY['inadvertent','not breach','fails to correct','ninety days','terminate','retain all rights']::text[], '{"doc": "Counterparty_Markup", "section": "Credit", "note": "Termination right for uncured credit error", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Termination with rights retention for credit errors is grossly disproportionate remedy. Credit issues cannot result in loss of Program rights."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall use reasonable efforts to include in its agreements with third-party distributors and licensees a requirement that such parties accord credit to talent in accordance with their contractual entitlements. Amazon shall have no liability for any third party''s failure to comply with credit obligations.', ARRAY['reasonable efforts','third-party distributors','licensees','accord credit','talent','contractual entitlements','no liability','third party failure']::text[], '{"doc": "PSA_Principal_Terms", "section": "Third-Party Credit", "note": "Standard reasonable efforts with no liability", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard Amazon position requiring only reasonable efforts to include credit provisions in third-party agreements, with explicit disclaimer of liability for third-party failures."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon agrees to use reasonable efforts to cause its licensees and sub-distributors to comply with applicable credit requirements. ProdCo acknowledges that Amazon has no privity of contract with such third parties and shall have no responsibility for their actions or omissions regarding credit.', ARRAY['reasonable efforts','licensees','sub-distributors','credit requirements','no privity','no responsibility','actions omissions']::text[], '{"doc": "PSA_Principal_Terms", "section": "Third-Party Credit", "note": "Privity acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes explicit acknowledgment of no privity, reinforcing that Amazon cannot guarantee third-party compliance. Standard protective language."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'With respect to third-party exploitation of the Program, Amazon shall use reasonable efforts to include credit provisions in its license agreements. Amazon does not warrant or guarantee that any third party will comply with such provisions and shall not be liable for any third party''s failure to do so.', ARRAY['third-party exploitation','reasonable efforts','credit provisions','license agreements','no warrant guarantee','not liable','failure']::text[], '{"doc": "PSA_Principal_Terms", "section": "Third-Party Credit", "note": "No warranty of compliance", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly disclaims warranty or guarantee of third-party compliance. ''Reasonable efforts to include'' is the appropriate standard."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall use reasonable efforts to include provisions in its distribution agreements requiring compliance with credit obligations. ProdCo agrees that Amazon shall not be required to police, monitor or enforce such provisions, and shall have no liability for any distributor''s failure to accord proper credit.', ARRAY['reasonable efforts','distribution agreements','credit obligations','not required to police','monitor','enforce','no liability','distributor failure']::text[], '{"doc": "PSA_Principal_Terms", "section": "Third-Party Credit", "note": "No policing obligation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly disclaims policing, monitoring, and enforcement obligations, which is essential as Amazon cannot practically oversee all third-party credit compliance."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon will use reasonable efforts to include credit requirements in agreements with third parties exploiting the Program. ProdCo''s sole recourse for any third party''s credit failure shall be directly against such third party, and not against Amazon.', ARRAY['reasonable efforts','credit requirements','third parties','sole recourse','directly against third party','not against Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "Third-Party Credit", "note": "Directs recourse to third party", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly directs ProdCo''s recourse to the breaching third party rather than Amazon. Important for avoiding Amazon as intermediary in credit disputes."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall include in its standard license agreements a provision requiring licensees to accord credit consistent with the Program''s credit block. Amazon shall have no liability for any licensee''s failure to comply, and ProdCo waives any claim against Amazon arising from such failure.', ARRAY['standard license agreements','licensees','credit block','no liability','waives claim','arising from failure']::text[], '{"doc": "PSA_Principal_Terms", "section": "Third-Party Credit", "note": "Includes waiver of claims", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Adds explicit waiver of claims against Amazon for third-party credit failures, providing additional protection beyond simple no-liability statement."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s obligations with respect to third-party credit compliance shall be limited to using reasonable efforts to include appropriate credit provisions in its license agreements. Amazon shall not be deemed in breach of this Agreement due to any act or omission of any third party regarding credit.', ARRAY['obligations limited','reasonable efforts','credit provisions','license agreements','not deemed in breach','act omission','third party']::text[], '{"doc": "PSA_Principal_Terms", "section": "Third-Party Credit", "note": "Limitation on Amazon''s obligation scope", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clearly limits scope of Amazon''s obligation to inclusion of provisions, explicitly stating third-party failures don''t constitute Amazon breach."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall use commercially reasonable efforts to include credit provisions in its third-party agreements and to notify such third parties of credit requirements. Amazon shall have no liability for third-party failures, but shall notify ProdCo if Amazon becomes aware of any material credit violation by a major licensee.', ARRAY['commercially reasonable efforts','credit provisions','notify third parties','no liability','notify ProdCo','material credit violation','major licensee']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Notice of material violations", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Notice requirement for material violations by major licensees adds obligation but is limited in scope. Legal should confirm this doesn''t create monitoring duty."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall use reasonable efforts to include credit provisions in third-party agreements. If ProdCo notifies Amazon of a third party''s credit failure and provides reasonable evidence thereof, Amazon shall use reasonable efforts to communicate with such third party regarding correction.', ARRAY['reasonable efforts','credit provisions','ProdCo notifies','reasonable evidence','communicate','third party','correction']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Communication upon ProdCo notice", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Obligation to communicate with third party upon ProdCo notice is additional but limited. ''Reasonable efforts'' standard and evidence requirement provide protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall use reasonable efforts to include credit provisions in distribution agreements. Amazon shall have no liability for third-party failures; provided that Amazon shall not affirmatively instruct any third party to omit or reduce credits that are required under this Agreement.', ARRAY['reasonable efforts','distribution agreements','no liability','not affirmatively instruct','omit reduce credits','required']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "No affirmative instruction to omit", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Prohibition on affirmatively instructing credit omission is reasonable and shouldn''t limit Amazon''s flexibility. Legal should confirm this is operationally acceptable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall include credit provisions in its material third-party license agreements (excluding short-form licenses, promotional licenses, and agreements with total value under $50,000). Amazon shall have no liability for any third party''s credit failure.', ARRAY['material third-party license agreements','excluding','short-form','promotional','under $50,000','no liability']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Carveouts for minor licenses", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Carveouts for minor licenses are reasonable as including credit provisions in every small deal is impractical. Legal should confirm thresholds are appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall use reasonable efforts to include credit provisions in third-party agreements. If Amazon enters into any license agreement that does not contain credit provisions, Amazon shall notify ProdCo of such omission within thirty (30) days.', ARRAY['reasonable efforts','credit provisions','license agreement','does not contain','notify ProdCo','omission','thirty days']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Notice of agreements without credit provisions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Notice requirement for agreements lacking credit provisions adds tracking burden. Legal should assess operational feasibility."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall use reasonable efforts to include credit provisions in its third-party agreements and shall provide ProdCo with copies of credit-related provisions from major distribution agreements (with financial terms redacted) upon reasonable request.', ARRAY['reasonable efforts','credit provisions','copies','credit-related provisions','major distribution agreements','redacted','reasonable request']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Copies of credit provisions upon request", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Providing copies of credit provisions (with financial terms redacted) upon request is additional but limited burden. Legal should confirm confidentiality concerns are addressed."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall ensure that all third-party distributors and licensees comply with credit obligations. Amazon shall be responsible for any third party''s failure to accord proper credit and shall indemnify ProdCo against any claims arising from such failure.', ARRAY['ensure','third-party distributors','licensees','comply','responsible','indemnify','claims','failure']::text[], '{"doc": "Counterparty_Proposal", "section": "Third-Party Credit", "note": "Amazon guarantee of third-party compliance", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Ensure'' creates guarantee obligation, and indemnification for third-party failures is unacceptable. Amazon cannot control third-party behavior."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall use best efforts to cause all third parties exploiting the Program to comply with credit requirements. Amazon shall be liable for any third party''s failure to accord credit as if such failure were Amazon''s own breach of this Agreement.', ARRAY['best efforts','cause','third parties','comply','liable','third party failure','Amazon''s own breach']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Best efforts with liability", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Best efforts'' is higher than reasonable efforts, and treating third-party failures as Amazon breach creates unacceptable liability exposure."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall include credit provisions in all third-party agreements and shall actively monitor and enforce such provisions. Amazon shall terminate any licensee that fails to comply with credit requirements after written notice.', ARRAY['include','all third-party agreements','actively monitor','enforce','terminate','fails to comply','written notice']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Active monitoring and enforcement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Active monitoring and enforcement obligation is operationally impractical. Termination requirement for credit non-compliance is grossly disproportionate."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall use reasonable efforts to include credit provisions in third-party agreements. If any third party fails to accord proper credit, Amazon shall pursue legal action against such third party at Amazon''s expense to enforce credit compliance.', ARRAY['reasonable efforts','credit provisions','third party fails','pursue legal action','Amazon''s expense','enforce credit compliance']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Litigation obligation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Obligation to pursue legal action against third parties for credit failures is unreasonable, costly, and disproportionate to the credit interest at stake."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall include credit provisions in third-party agreements and shall be jointly and severally liable with any third party that fails to comply with credit requirements. ProdCo may pursue claims against Amazon or the third party, or both.', ARRAY['credit provisions','jointly and severally liable','third party','fails to comply','pursue claims','Amazon or third party']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Joint and several liability", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Joint and several liability with third parties for credit failures is completely unacceptable. Amazon cannot be liable for entities it doesn''t control."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall include credit provisions in third-party agreements. Amazon''s no-liability protection shall not apply if Amazon failed to include such provisions or if Amazon approved any third-party materials that contained credit errors prior to distribution.', ARRAY['credit provisions','no-liability','not apply','failed to include','approved','credit errors','prior to distribution']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Exceptions to no-liability", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Creating exceptions to no-liability for approval of materials or inclusion failures significantly undermines protection. Amazon cannot review all third-party materials for credit accuracy."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall use reasonable efforts to include credit provisions in third-party agreements. If any third party fails to accord proper credit, Amazon shall pay ProdCo liquidated damages of $25,000 per occurrence, regardless of whether Amazon bears fault for such failure.', ARRAY['reasonable efforts','third party fails','liquidated damages','$25,000','per occurrence','regardless of fault']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Liquidated damages for third-party failures", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Liquidated damages for third-party credit failures regardless of Amazon fault is completely unacceptable. Amazon cannot be penalized for conduct it doesn''t control."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall contractually require its distributors and licensees to accord credit in accordance with the Program''s credit block. Notwithstanding the foregoing, Amazon shall have no obligation to police or monitor such compliance and shall have no liability for any distributor''s or licensee''s failure to comply.', ARRAY['contractually require','distributors','licensees','credit block','no obligation','police','monitor','no liability','failure to comply']::text[], '{"doc": "PSA_Fallbacks", "section": "Third-Party Credit", "note": "Contractual bind with no police/no liability", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Upgrade from ''reasonable efforts'' to ''contractually require'' is a give that requires Legal approval. No-police and no-liability protections remain essential."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon agrees to include binding credit provisions in its license agreements with third parties. ProdCo acknowledges that Amazon shall not be required to enforce such provisions or to monitor third-party compliance, and Amazon shall not be liable for any third party''s credit failure.', ARRAY['binding credit provisions','license agreements','not required to enforce','monitor','not liable','third party credit failure']::text[], '{"doc": "PSA_Fallbacks", "section": "Third-Party Credit", "note": "Binding provisions with enforcement disclaimer", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Binding provisions language is stronger than reasonable efforts but paired with appropriate enforcement and liability disclaimers. Requires Legal approval."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall include in its distribution agreements a contractual requirement that distributors provide credit consistent with talent agreements. Amazon shall have no responsibility for policing such agreements, and ProdCo''s sole recourse for any credit violation shall be against the violating distributor.', ARRAY['contractual requirement','distributors','credit','talent agreements','no responsibility','policing','sole recourse','violating distributor']::text[], '{"doc": "PSA_Fallbacks", "section": "Third-Party Credit", "note": "Sole recourse against distributor", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Directs recourse exclusively to violating distributor, maintaining Amazon''s protection despite contractual-bind obligation. Requires Legal approval."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall contractually bind its major territorial licensees to accord credit in accordance with this Agreement. ''Major territorial licensees'' means licensees with rights in territories generating at least 5% of worldwide Program revenue. Amazon shall have no policing obligation and no liability for non-compliance.', ARRAY['contractually bind','major territorial licensees','5%','worldwide revenue','no policing obligation','no liability','non-compliance']::text[], '{"doc": "PSA_Fallbacks", "section": "Third-Party Credit", "note": "Limited to major licensees", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limiting contractual-bind obligation to major licensees (defined by revenue threshold) is reasonable scope limitation. Requires Legal approval."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'With respect to third-party exploitation, Amazon shall include credit requirements in its license agreements as contractual provisions. Amazon expressly disclaims any duty to police, monitor, audit or enforce such provisions, and shall have no liability whatsoever for any licensee''s failure to comply with credit requirements.', ARRAY['credit requirements','contractual provisions','disclaims duty','police','monitor','audit','enforce','no liability','licensee failure']::text[], '{"doc": "PSA_Fallbacks", "section": "Third-Party Credit", "note": "Comprehensive disclaimer of duties", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Comprehensive disclaimer covering police, monitor, audit, and enforce provides robust protection alongside contractual-bind commitment. Requires Legal approval."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall contractually require third-party distributors to accord credit. If Amazon becomes aware of a material credit violation and ProdCo requests in writing, Amazon shall send a single written notice to the violating distributor requesting correction. Amazon shall have no further obligation and no liability regardless of whether correction occurs.', ARRAY['contractually require','becomes aware','material credit violation','written request','single written notice','requesting correction','no further obligation','no liability']::text[], '{"doc": "PSA_Fallbacks", "section": "Third-Party Credit", "note": "Single notice upon request", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Commitment to send single notice upon request is limited additional obligation that doesn''t create enforcement duty. Requires Legal approval."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon agrees to contractually bind its licensees to credit compliance obligations. ProdCo acknowledges that: (a) Amazon cannot guarantee third-party compliance; (b) Amazon has no duty to police or enforce such provisions; (c) Amazon shall have no liability for third-party credit failures; and (d) ProdCo''s sole remedy is against the non-compliant third party.', ARRAY['contractually bind','licensees','cannot guarantee','no duty','police','enforce','no liability','sole remedy','non-compliant third party']::text[], '{"doc": "PSA_Fallbacks", "section": "Third-Party Credit", "note": "Enumerated acknowledgments", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Enumerated acknowledgments reinforce that contractual-bind commitment doesn''t expand Amazon''s liability or enforcement obligations. Requires Legal approval."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall contractually require its licensees to comply with credit requirements. Upon ProdCo''s written request identifying a specific credit violation with supporting evidence, Amazon shall forward ProdCo''s complaint to the relevant licensee. Amazon shall have no further obligation and no liability.', ARRAY['contractually require','written request','specific violation','supporting evidence','forward complaint','no further obligation','no liability']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Complaint forwarding upon request", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Complaint forwarding is ministerial act that doesn''t create enforcement obligation. Evidence requirement provides protection against frivolous requests. Requires Legal review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall contractually bind licensees to credit obligations and shall have no policing duty or liability. If Amazon terminates or does not renew any licensee agreement for any reason, Amazon shall use reasonable efforts to require the successor licensee to correct any known credit deficiencies.', ARRAY['contractually bind','no policing','no liability','terminates','does not renew','successor licensee','correct','known credit deficiencies']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Successor licensee obligation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Successor licensee credit correction is limited obligation triggered only by licensee transition. ''Known deficiencies'' limits scope. Requires Legal review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall include binding credit provisions in third-party agreements. Amazon shall have no policing obligation or liability; provided that if Amazon exercises any contractual remedy against a licensee for material breach unrelated to credit, Amazon shall consider in good faith including credit violations in any such enforcement action if raised by ProdCo.', ARRAY['binding credit provisions','no policing','no liability','exercises remedy','material breach','consider in good faith','credit violations','enforcement action']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Piggyback on other enforcement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Considering credit issues when already pursuing other enforcement is limited obligation that doesn''t create independent enforcement duty. Requires Legal review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall contractually require credit compliance by third parties. Amazon shall not be required to police such agreements; however, Amazon shall include in its form license agreements a provision allowing ProdCo (as third-party beneficiary for credit provisions only) to enforce credit requirements directly against the licensee.', ARRAY['contractually require','not required to police','form license agreements','third-party beneficiary','credit provisions only','enforce directly','licensee']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Third-party beneficiary rights", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Third-party beneficiary status for ProdCo on credit provisions shifts enforcement burden from Amazon to ProdCo but creates privity concerns. Requires careful Legal review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall contractually bind licensees to accord credit. If any licensee persistently fails to accord proper credit after multiple notices (three or more) and ProdCo requests in writing, Amazon shall consider in good faith whether to include such failure as a factor in future license renewal decisions.', ARRAY['contractually bind','persistently fails','multiple notices','three or more','written request','consider in good faith','license renewal']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Consideration in renewal decisions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Good faith consideration of credit failures in renewal decisions is weak commitment that preserves Amazon discretion. ''Persistent'' and ''multiple notices'' thresholds provide protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall contractually require credit compliance. Amazon shall have no policing obligation or liability for third-party failures. Notwithstanding the foregoing, Amazon shall provide ProdCo upon written request with contact information for the person responsible for credit matters at any major licensee, so ProdCo may communicate directly.', ARRAY['contractually require','no policing','no liability','provide upon request','contact information','credit matters','major licensee','communicate directly']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Contact information sharing", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Providing contact information for direct ProdCo communication is minimal burden that empowers ProdCo without creating Amazon enforcement obligations. Requires Legal approval."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall contractually require all third parties to comply with credit provisions and shall actively enforce such provisions. If any third party fails to accord proper credit, Amazon shall pursue all available legal remedies at Amazon''s cost to compel compliance.', ARRAY['contractually require','actively enforce','fails','pursue','legal remedies','Amazon''s cost','compel compliance']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Active enforcement obligation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Active enforcement and litigation obligation is unacceptable regardless of contractual-bind commitment. Amazon cannot be required to sue third parties over credit."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall contractually bind all third parties to credit compliance. Amazon shall monitor all third-party exploitation for credit compliance on an ongoing basis and shall notify ProdCo within seven (7) days of any credit violation discovered.', ARRAY['contractually bind','monitor','all third-party exploitation','ongoing basis','notify ProdCo','seven days','violation discovered']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Ongoing monitoring obligation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Ongoing monitoring obligation is operationally impractical and directly contradicts the no-police protection that is essential to the contractual-bind give."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall contractually require credit compliance. If any third party materially violates credit requirements, Amazon shall terminate such licensee''s agreement within thirty (30) days of written notice from ProdCo, or Amazon shall be liable to ProdCo for the third party''s continuing violations.', ARRAY['contractually require','materially violates','terminate','thirty days','written notice','liable','continuing violations']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Mandatory termination or liability", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mandatory termination for credit violations or assumption of liability is grossly disproportionate and unacceptable. Credit issues cannot dictate major business relationships."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall contractually bind licensees to credit provisions. Amazon shall be deemed to have policing and enforcement obligations with respect to credit provisions, and any third party''s credit failure shall be deemed Amazon''s failure for purposes of this Agreement.', ARRAY['contractually bind','deemed','policing','enforcement obligations','third party failure','deemed Amazon''s failure']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Third-party failures imputed to Amazon", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Deeming third-party failures as Amazon failures directly contradicts the no-liability protection and creates unacceptable exposure."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall contractually require credit compliance. Amazon''s no-policing and no-liability protections shall apply only to immaterial credit errors. For material credit violations (affecting main titles or key creative credits), Amazon shall actively enforce and shall be liable if enforcement is not pursued.', ARRAY['contractually require','no-policing','no-liability','immaterial only','material violations','main titles','key creative','actively enforce','liable']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Carveout for material violations", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Carving out ''material'' violations from no-liability protection creates significant exposure for the most visible credits and is unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall include credit provisions in third-party agreements as binding obligations. If Amazon fails to include such provisions in any agreement, Amazon shall indemnify ProdCo against any losses arising from that third party''s failure to accord proper credit.', ARRAY['credit provisions','binding obligations','fails to include','indemnify','losses','third party failure']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Indemnity for failure to include provisions", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Indemnification for failing to include credit provisions creates disproportionate exposure. The remedy for inclusion failure shouldn''t be full liability for third-party conduct."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall contractually require credit compliance and shall audit all major licensees annually for credit compliance. Amazon shall share audit results with ProdCo and shall withhold a portion of license fees from any non-compliant licensee until compliance is achieved.', ARRAY['contractually require','audit','major licensees','annually','credit compliance','share audit results','withhold','license fees','non-compliant']::text[], '{"doc": "Counterparty_Markup", "section": "Third-Party Credit", "note": "Annual audit and fee withholding", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Annual credit audits and fee withholding obligations are operationally burdensome and disproportionate to credit interests. Completely unacceptable."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall have sole and final control over all aspects of the development, production, post-production, marketing, distribution and exploitation of the Program, including without limitation all creative, editorial, technical and business decisions.', ARRAY['sole and final control','all aspects','development','production','post-production','marketing','distribution','exploitation','creative','editorial','technical','business decisions']::text[], '{"doc": "PSA_Principal_Terms", "section": "Control", "note": "Standard comprehensive control provision", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard Amazon position establishing complete control over all Program-related decisions. Essential for maintaining creative and business autonomy over the content."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All decisions regarding the Program shall be made by Amazon in its sole discretion, including decisions relating to casting, scripting, directing, producing, editing, marketing, release timing, platforms, territories and any other matter affecting the Program.', ARRAY['all decisions','sole discretion','casting','scripting','directing','producing','editing','marketing','release timing','platforms','territories']::text[], '{"doc": "PSA_Principal_Terms", "section": "Control", "note": "Enumerated control elements", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific control elements to provide additional clarity. Comprehensive list reinforces Amazon''s unilateral decision-making authority."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall have the sole right to determine the final form and content of the Program. Amazon may edit, modify, add to, subtract from, rearrange, adapt or otherwise alter the Program in any manner without limitation and without any requirement to consult with or obtain approval from ProdCo.', ARRAY['sole right','final form content','edit','modify','add','subtract','rearrange','adapt','alter','without limitation','no consultation','no approval']::text[], '{"doc": "PSA_Principal_Terms", "section": "Control", "note": "Editorial control specifics", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly addresses editorial modifications without consultation or approval, ensuring Amazon can make any changes needed for creative, regulatory, or commercial reasons."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo acknowledges and agrees that Amazon shall exercise sole and final control over the Program and that ProdCo shall have no approval, consultation or veto rights with respect to any decision relating to the Program.', ARRAY['acknowledges agrees','sole and final control','no approval','no consultation','no veto rights','any decision']::text[], '{"doc": "PSA_Principal_Terms", "section": "Control", "note": "Explicit waiver of ProdCo rights", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit acknowledgment that ProdCo has no approval, consultation, or veto rights reinforces Amazon''s control and prevents future disputes about implied rights."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s control over the Program shall be absolute and unfettered. Amazon shall not be required to produce, complete, release, distribute or continue to exploit the Program, and all such decisions shall be within Amazon''s sole discretion.', ARRAY['absolute unfettered','not required','produce','complete','release','distribute','exploit','sole discretion']::text[], '{"doc": "PSA_Principal_Terms", "section": "Control", "note": "Includes no-release discretion", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly includes discretion not to produce, release, or exploit the Program, which is essential for avoiding any implied commitment to release."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall have sole and final control over all Program matters. ProdCo shall render services strictly in accordance with Amazon''s instructions and directions, and shall implement all changes, revisions or modifications requested by Amazon promptly and without objection.', ARRAY['sole and final control','render services','Amazon''s instructions','directions','implement changes','revisions','modifications','promptly','without objection']::text[], '{"doc": "PSA_Principal_Terms", "section": "Control", "note": "Service delivery subject to control", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Connects Amazon''s control to ProdCo''s service obligations, ensuring ProdCo must follow Amazon direction without resistance or delay."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon shall exercise sole and final creative and business control over the Programme. Without limiting the foregoing, Amazon shall have the exclusive right to determine all matters relating to format, length, rating, language versions, accessibility features, territorial release strategy and platform prioritisation.', ARRAY['sole and final','creative','business control','format','length','rating','language versions','accessibility','territorial release','platform prioritisation']::text[], '{"doc": "PSA_Principal_Terms", "section": "Control", "note": "UK production with platform specifics", "approval": null, "jurisdiction": "UK", "risk_level": "LOW", "reasoning": "UK-appropriate spelling with specific streaming platform considerations (accessibility, platform prioritization). Comprehensive control provision."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall have sole and final control over the Program. Notwithstanding the foregoing, Amazon shall consult with ProdCo regarding key creative decisions, including selection of director and principal cast, provided that Amazon shall retain final decision-making authority.', ARRAY['sole and final control','consult','key creative decisions','director','principal cast','final decision-making authority']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Consultation on key creative", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Consultation (without approval) on key creative decisions may be acceptable for major producers if Amazon retains final authority. Requires Legal approval."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall have sole and final control over the Program in all respects. If Amazon contemplates a material change to the approved production budget or shooting schedule, Amazon shall provide ProdCo reasonable advance notice of such change.', ARRAY['sole and final control','material change','approved production budget','shooting schedule','reasonable advance notice']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Notice for budget/schedule changes", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Notice (not approval) for budget/schedule changes is minimal impact on control and may be operationally reasonable. Requires Legal review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall exercise sole and final control over the Program. Amazon agrees to consider in good faith any creative input provided by ProdCo, though Amazon shall have no obligation to accept or incorporate such input and shall retain final authority over all decisions.', ARRAY['sole and final control','consider in good faith','creative input','no obligation','accept incorporate','final authority']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Good faith consideration of input", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "''Consider in good faith'' with explicit disclaimer of obligation to accept is low-impact accommodation. May be appropriate for relationship purposes."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall have sole and final control over the Program. If Amazon decides not to proceed with production of the Program after commencement of pre-production, Amazon shall notify ProdCo in writing and pay any documented wind-down costs reasonably incurred by ProdCo.', ARRAY['sole and final control','decides not to proceed','commencement of pre-production','notify','writing','wind-down costs','reasonably incurred']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Wind-down costs on cancellation", "approval": "BUSINESS_AFFAIRS", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Wind-down costs for post-pre-production cancellation is a commercial term that doesn''t affect control. Business Affairs should assess scope and caps."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall have sole and final control over the Program, subject to compliance with applicable laws and regulations, guild and union requirements, and any third-party agreements to which Amazon has consented in writing.', ARRAY['sole and final control','subject to','applicable laws','regulations','guild union','third-party agreements','consented in writing']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Subject to laws/guilds/consented agreements", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Carveouts for laws, regulations, and Amazon-consented agreements are inherent limitations that don''t expand ProdCo rights. Legal should confirm scope."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon shall exercise sole and final control over the Program. ProdCo may request Amazon''s reconsideration of any creative decision by written notice setting forth ProdCo''s concerns; Amazon shall respond to any such request within five (5) business days but shall not be obligated to change any decision.', ARRAY['sole and final control','request reconsideration','creative decision','written notice','concerns','respond','five business days','not obligated']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Reconsideration request process", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Formal reconsideration process is additional procedure but doesn''t limit Amazon''s decision authority. Requires Legal assessment of operational impact."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon and ProdCo shall jointly exercise control over the Program. All material creative and business decisions shall require the mutual written approval of both parties.', ARRAY['jointly','control','material creative','business decisions','mutual written approval','both parties']::text[], '{"doc": "Counterparty_Proposal", "section": "Control", "note": "Joint control proposal", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Joint control fundamentally undermines Amazon''s position as sole owner and decision-maker. Creates potential for deadlock and is completely unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall have control over distribution and marketing of the Program. ProdCo shall have creative control over the Program, including final cut authority, and Amazon shall not make any creative changes without ProdCo''s prior written consent.', ARRAY['Amazon distribution marketing','ProdCo creative control','final cut','no creative changes','prior written consent']::text[], '{"doc": "Counterparty_Proposal", "section": "Control", "note": "Split control with ProdCo final cut", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Splitting control gives ProdCo creative authority that conflicts with Amazon''s ownership. Final cut authority for ProdCo is completely unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall have sole and final control over the Program, except that ProdCo shall have approval rights over the following: (a) selection of director; (b) selection of principal cast; (c) final script; (d) final cut; and (e) any material changes to the approved budget.', ARRAY['sole and final control','except','ProdCo approval rights','director','principal cast','final script','final cut','budget changes']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Major approval rights reserved to ProdCo", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo approval over director, cast, script, final cut, and budget represents near-total creative control. These carveouts eviscerate Amazon''s control."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall exercise control over the Program in a manner consistent with ProdCo''s creative vision for the series as set forth in the Series Bible attached hereto. Amazon shall not deviate materially from the Series Bible without ProdCo''s consent.', ARRAY['control','consistent with','ProdCo''s creative vision','Series Bible','not deviate','materially','ProdCo''s consent']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Bound by Series Bible", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Binding Amazon to ProdCo''s ''creative vision'' in a Series Bible with consent requirement for deviations gives ProdCo effective creative control. Not acceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall have control over the Program. However, ProdCo shall have the right to remove ProdCo''s name and any credit from the Program if Amazon makes creative decisions that ProdCo, in its reasonable judgment, determines are inconsistent with ProdCo''s professional reputation.', ARRAY['control','however','remove name','credit','creative decisions','reasonable judgment','inconsistent','professional reputation']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Reputation-based removal right", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Reputation-based removal right creates implicit pressure on Amazon''s creative decisions. While not a formal approval right, it functions as a constraint on Amazon''s control."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s control over the Program shall be subject to the oversight of a Creative Committee consisting of two representatives from Amazon and two representatives from ProdCo. Decisions of the Creative Committee shall be made by majority vote.', ARRAY['control subject to','oversight','Creative Committee','two representatives','Amazon','ProdCo','majority vote']::text[], '{"doc": "Counterparty_Proposal", "section": "Control", "note": "Creative Committee oversight", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Creative Committee with equal representation creates deadlock risk and shared control. Majority vote structure cannot function with 2-2 composition. Completely unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon shall exercise reasonable control over the Program in accordance with industry-standard production practices. ProdCo shall have the right to dispute any Amazon decision that deviates from such practices, with disputes to be resolved by an independent production consultant.', ARRAY['reasonable control','industry-standard','production practices','right to dispute','deviates','disputes resolved','independent consultant']::text[], '{"doc": "Counterparty_Markup", "section": "Control", "note": "Industry standard limitation with disputes", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Reasonable control'' with industry-standard limitation and dispute resolution undermines sole control. Independent consultant decisions would override Amazon authority."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not issue or authorize any press release, publicity, announcement or other public statement regarding the Program, this Agreement or ProdCo''s relationship with Amazon without Amazon''s prior written approval.', ARRAY['not issue','authorize','press release','publicity','announcement','public statement','Program','Agreement','relationship','prior written approval']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Standard publicity restriction", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard Amazon position requiring prior written approval for all publicity. Essential for controlling messaging around the Program and Amazon relationship."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All publicity, marketing, promotion and advertising relating to the Program shall be controlled exclusively by Amazon. ProdCo shall not make any public statement or disclosure about the Program without Amazon''s prior written consent, which may be withheld in Amazon''s sole discretion.', ARRAY['publicity','marketing','promotion','advertising','controlled exclusively','Amazon','no public statement','disclosure','prior written consent','sole discretion']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Comprehensive marketing control", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive language covering all forms of public communication with explicit sole discretion standard for consent."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain strict confidentiality regarding the Program and shall not disclose any information about the Program to any third party, including media outlets, without Amazon''s prior written approval. This restriction applies during production and in perpetuity thereafter.', ARRAY['strict confidentiality','not disclose','information','third party','media outlets','prior written approval','during production','perpetuity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Perpetual publicity restriction", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Perpetual restriction ensures ProdCo cannot make unauthorized statements even after production or release. Essential for long-term control."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not issue any publicity without Amazon''s prior written approval. Without limiting the foregoing, ProdCo shall not post any content relating to the Program on any social media platform, website, blog or other digital medium without Amazon''s express authorization.', ARRAY['no publicity','prior written approval','not post','content','social media','website','blog','digital medium','express authorization']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Includes social media restriction", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly covers social media and digital platforms, which are increasingly important channels that require Amazon control."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All publicity relating to the Program requires Amazon''s prior written approval. ProdCo shall submit any proposed publicity materials to Amazon at least ten (10) business days in advance, and Amazon shall have the right to approve, reject or require modifications to such materials.', ARRAY['all publicity','prior written approval','submit','proposed materials','ten business days','advance','approve','reject','require modifications']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Submission and review process", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Establishes clear submission and review process with adequate lead time for Amazon review. Right to require modifications ensures complete control."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not make any public statement regarding the Program without Amazon''s prior approval. ProdCo shall ensure that all of its employees, contractors, agents and representatives comply with this restriction and shall be responsible for any unauthorized publicity by such persons.', ARRAY['no public statement','prior approval','ensure','employees','contractors','agents','representatives','comply','responsible','unauthorized publicity']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Extends to ProdCo personnel", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Extends publicity restriction to all ProdCo personnel and makes ProdCo responsible for their compliance. Essential for practical enforcement."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'No publicity shall be issued without Amazon''s prior written approval. For the avoidance of doubt, this restriction covers interviews, panel appearances, podcasts, trade publication articles, industry event presentations, award campaign materials and any other form of public communication relating to the Program.', ARRAY['no publicity','prior written approval','interviews','panel appearances','podcasts','trade publications','industry events','award campaigns','public communication']::text[], '{"doc": "PSA_Principal_Terms", "section": "Publicity", "note": "Comprehensive enumeration", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Detailed enumeration of publicity formats prevents arguments that certain types of communication fall outside the restriction."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall not issue publicity without Amazon''s prior written approval, except that ProdCo may include a brief, factual reference to the Program in ProdCo''s corporate communications (e.g., investor reports, company website bio) describing ProdCo''s slate of productions.', ARRAY['no publicity','prior written approval','except','brief factual reference','corporate communications','investor reports','website bio','slate']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Corporate communications carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited carveout for factual corporate communications may be acceptable for established production companies. Legal should review to ensure scope is narrow."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo requires Amazon''s prior approval for all publicity. Notwithstanding the foregoing, after the Program''s initial public release, ProdCo may make general statements acknowledging ProdCo''s involvement with the Program without disclosing confidential information or plot details.', ARRAY['prior approval','all publicity','notwithstanding','after initial release','general statements','acknowledging involvement','no confidential information','plot details']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Post-release acknowledgment carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Post-release acknowledgment of involvement without confidential/plot disclosure may be acceptable. Legal should define ''general statements'' more precisely."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall obtain Amazon''s prior approval for all publicity. Amazon shall respond to ProdCo''s approval requests within five (5) business days; failure to respond shall be deemed approval for purposes of this provision only.', ARRAY['prior approval','all publicity','respond','five business days','failure to respond','deemed approval']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Deemed approval for non-response", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Deemed approval on non-response creates risk of inadvertent approval. Legal should assess whether 5-day window is adequate for review and whether this is operationally workable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'No publicity without Amazon''s prior approval. ProdCo may respond to direct media inquiries by referring the inquiry to Amazon''s publicity department; provided that ProdCo shall not provide any substantive response without Amazon''s approval.', ARRAY['no publicity','prior approval','respond','media inquiries','referring','Amazon''s publicity','no substantive response']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Referral of media inquiries", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Allowing ProdCo to refer inquiries to Amazon (without substantive response) is procedurally helpful and doesn''t undermine control. Requires Legal confirmation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo requires Amazon''s prior written approval for publicity. If ProdCo is nominated for or receives an industry award relating to the Program, ProdCo may make acceptance speeches and participate in press events customary for such awards, provided ProdCo does not disclose NPI.', ARRAY['prior written approval','publicity','nominated','industry award','acceptance speeches','press events','customary','no NPI disclosure']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Award ceremony carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Award ceremony participation is expected and blocking it could damage relationships. NPI protection is maintained. Legal should confirm scope of ''customary'' activities."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'All publicity requires Amazon''s prior approval. Amazon hereby grants ongoing approval for ProdCo to use the approved Program logline and key art provided by Amazon in ProdCo''s portfolio and website, subject to Amazon''s right to revoke such approval upon written notice.', ARRAY['prior approval','ongoing approval','approved logline','key art','portfolio','website','revoke','written notice']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Pre-approved portfolio use", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Pre-approval for specific approved materials in portfolio with revocation right is limited grant that may be acceptable. Requires Legal review."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may issue publicity regarding the Program at any time without Amazon''s approval, provided such publicity does not contain false or misleading information. ProdCo shall provide Amazon with copies of any publicity materials within five (5) business days of release.', ARRAY['may issue','without approval','not false misleading','provide copies','five business days','after release']::text[], '{"doc": "Counterparty_Proposal", "section": "Publicity", "note": "No prior approval required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Eliminating prior approval requirement gives ProdCo complete publicity freedom. After-the-fact copies are useless for controlling messaging. Completely unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo requires Amazon''s approval for publicity, which approval shall not be unreasonably withheld, conditioned or delayed. Amazon shall be deemed to have acted unreasonably if it fails to approve factually accurate publicity within three (3) business days.', ARRAY['approval','not unreasonably withheld','conditioned','delayed','deemed unreasonable','factually accurate','three business days']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Reasonableness standard with deemed approval", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Not unreasonably withheld'' with 3-day deemed approval effectively eliminates Amazon''s publicity control. Amazon needs sole discretion over all publicity."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s approval is required for ProdCo publicity. However, ProdCo''s principals may discuss the Program freely on their personal social media accounts and in personal interviews, as such statements are personal expression and not official ProdCo communications.', ARRAY['approval required','however','principals','personal social media','personal interviews','personal expression','not official']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Personal social media carveout", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Carveout for principals'' ''personal'' social media and interviews creates massive loophole. Personal/official distinction is unworkable and defeats publicity control."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall not issue publicity without Amazon''s approval. If Amazon denies approval, Amazon shall provide ProdCo a written explanation of the denial and ProdCo shall have the right to appeal the denial to Amazon''s Head of Communications for final determination.', ARRAY['not issue','without approval','denies','written explanation','right to appeal','Head of Communications','final determination']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Appeal process for denials", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Appeal process for publicity denials undermines Amazon''s control by creating escalation mechanism. Written explanations for denials create unnecessary burden."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Publicity requires Amazon''s approval, except for communications required by law, regulation, or court order. ProdCo may also issue publicity if necessary to protect ProdCo''s business reputation from material harm, with notice to Amazon concurrent with release.', ARRAY['approval','except','required by law','court order','protect reputation','material harm','notice concurrent']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Reputation protection carveout", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "''Reputation protection'' carveout is subjective and could be invoked to justify any self-serving publicity. This exception is too broad."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo requires Amazon''s prior approval for formal press releases. All other publicity, including social media posts, interviews, industry event appearances and behind-the-scenes content, shall be at ProdCo''s discretion with contemporaneous notice to Amazon.', ARRAY['prior approval','formal press releases','all other publicity','social media','interviews','events','BTS','ProdCo discretion','contemporaneous notice']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Limited to formal press releases only", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting approval to ''formal press releases'' only while freeing everything else defeats the purpose of publicity control. Most modern publicity occurs outside formal press releases."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Publicity approval is required. Amazon agrees not to deny approval for any publicity that is substantially similar in tone and content to publicity previously approved by Amazon for this Program or other similar Amazon productions.', ARRAY['approval required','not deny','substantially similar','tone content','previously approved','similar productions']::text[], '{"doc": "Counterparty_Markup", "section": "Publicity", "note": "Precedent-based approval obligation", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "''Substantially similar'' standard based on prior approvals creates precedent-lock that limits Amazon''s ability to evolve publicity strategy or respond to changing circumstances."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not use any Amazon trademarks, service marks, trade names, logos or other proprietary designations without Amazon''s prior written approval in each instance.', ARRAY['not use','Amazon trademarks','service marks','trade names','logos','proprietary designations','prior written approval','each instance']::text[], '{"doc": "PSA_Principal_Terms", "section": "Trademarks", "note": "Standard trademark restriction", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard Amazon position requiring prior approval for each use of Amazon marks. Essential for trademark protection and brand control."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Use of Amazon''s trademarks, including without limitation the Amazon logo, Prime Video logo, and any Program-specific marks created by Amazon, requires Amazon''s prior written approval. Any approved use must comply with Amazon''s then-current trademark guidelines.', ARRAY['Amazon''s trademarks','Amazon logo','Prime Video logo','Program-specific marks','prior written approval','trademark guidelines']::text[], '{"doc": "PSA_Principal_Terms", "section": "Trademarks", "note": "Includes guidelines compliance", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicitly references specific Amazon marks and requires compliance with trademark guidelines. Comprehensive trademark protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not use any Amazon marks without prior written approval. All goodwill arising from any approved use of Amazon marks shall inure solely to Amazon''s benefit. ProdCo shall not register or attempt to register any mark confusingly similar to Amazon''s marks.', ARRAY['not use','Amazon marks','prior written approval','goodwill','inure','Amazon''s benefit','not register','confusingly similar']::text[], '{"doc": "PSA_Principal_Terms", "section": "Trademarks", "note": "Goodwill and registration protection", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes essential goodwill inurement and anti-registration provisions to prevent ProdCo from claiming rights in Amazon marks."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Prior written approval is required for use of Amazon marks. ProdCo acknowledges that Amazon is the sole owner of all Amazon trademarks and that ProdCo has no rights in such marks except as expressly authorized in writing by Amazon. Such authorization may be revoked at any time.', ARRAY['prior written approval','Amazon marks','sole owner','no rights','except expressly authorized','writing','revoked','any time']::text[], '{"doc": "PSA_Principal_Terms", "section": "Trademarks", "note": "Ownership acknowledgment with revocability", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Explicit ownership acknowledgment and revocability provision ensures Amazon maintains complete control over its marks."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s prior written approval is required for any use of Amazon trademarks. ProdCo shall submit proposed uses to Amazon for approval at least fifteen (15) business days in advance, including mock-ups or samples showing the proposed use in context.', ARRAY['prior written approval','Amazon trademarks','submit proposed uses','fifteen business days','advance','mock-ups','samples','context']::text[], '{"doc": "PSA_Principal_Terms", "section": "Trademarks", "note": "Submission process with mock-ups", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Establishes clear submission process with adequate lead time and requires contextual mock-ups for proper review."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Use of Amazon marks requires prior written approval. If Amazon approves any use, such approval shall be limited to the specific use, medium, territory and time period approved, and shall not constitute approval for any other or extended use.', ARRAY['prior written approval','Amazon marks','limited','specific use','medium','territory','time period','not constitute','other','extended use']::text[], '{"doc": "PSA_Principal_Terms", "section": "Trademarks", "note": "Narrow scope of approval", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Limits each approval to specific parameters, preventing ProdCo from extrapolating one approval to cover other uses."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not use Amazon trademarks without prior written approval. ProdCo shall not use Amazon marks in any manner that suggests Amazon endorses, sponsors or is affiliated with ProdCo''s other business activities or productions not covered by this Agreement.', ARRAY['not use','Amazon trademarks','prior written approval','not suggest','endorses','sponsors','affiliated','other business','other productions']::text[], '{"doc": "PSA_Principal_Terms", "section": "Trademarks", "note": "No implied endorsement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Prevents ProdCo from leveraging Amazon relationship to imply endorsement of unrelated activities. Important brand protection."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s prior written approval is required for use of Amazon marks. Amazon hereby grants ongoing approval for ProdCo to use the standard ''An Amazon Original'' credit block provided by Amazon, in the format and placement specified by Amazon, in connection with the Program only.', ARRAY['prior written approval','ongoing approval','Amazon Original','credit block','format','placement','specified','Program only']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Pre-approved credit block use", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Pre-approval for standard Amazon-provided credit block in specified format is controlled, limited use that may be acceptable. Requires Legal confirmation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Prior approval required for Amazon marks. Amazon shall respond to approval requests within ten (10) business days. If Amazon does not respond within such period, ProdCo may send a reminder notice, and if Amazon does not respond within five (5) additional business days, approval shall be deemed granted for the specific requested use only.', ARRAY['prior approval','ten business days','respond','reminder notice','five additional days','deemed granted','specific use only']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Deemed approval with reminder", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Deemed approval with reminder requirement and 15-day total window provides some protection. Legal should assess whether this is operationally acceptable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Use of Amazon marks requires prior approval. Notwithstanding the foregoing, ProdCo may use Amazon marks in factual descriptions of ProdCo''s relationship with Amazon (e.g., ''produced for Amazon'') in ProdCo''s corporate materials, provided such use is textual only and does not incorporate Amazon logos.', ARRAY['prior approval','notwithstanding','factual descriptions','relationship','produced for Amazon','corporate materials','textual only','no logos']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Textual reference carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited carveout for textual references (no logos) in corporate materials may be acceptable. Legal should confirm ''factual descriptions'' is sufficiently narrow."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s prior written approval is required for trademark use. For any use in connection with the Program''s marketing or distribution, Amazon shall not unreasonably withhold approval of uses that comply with Amazon''s brand guidelines, provided ProdCo submits such uses with adequate lead time.', ARRAY['prior written approval','marketing','distribution','not unreasonably withhold','brand guidelines','adequate lead time']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Not unreasonably withheld for guideline-compliant use", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "''Not unreasonably withheld'' for guideline-compliant uses in Program marketing context may be acceptable given the guideline compliance requirement. Requires Legal review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Prior written approval is required for Amazon marks. If ProdCo requests approval for a specific use and Amazon does not respond within the specified review period, ProdCo may escalate the request to Amazon''s designated trademark contact, who shall respond within three (3) business days.', ARRAY['prior written approval','does not respond','review period','escalate','designated trademark contact','three business days']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Escalation for non-response", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Escalation process for non-response doesn''t create deemed approval but provides procedural pathway. May be acceptable for operational purposes."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon''s approval is required for use of Amazon trademarks. Upon termination of this Agreement for any reason, ProdCo shall immediately cease all use of Amazon marks and shall remove or cover Amazon marks from any materials in ProdCo''s possession within thirty (30) days.', ARRAY['approval required','termination','immediately cease','all use','remove','cover','materials','possession','thirty days']::text[], '{"doc": "PSA_Fallbacks", "section": "Trademarks", "note": "Post-termination cessation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Post-termination cessation requirement reinforces Amazon''s trademark control. 30-day removal period may be acceptable for practical purposes."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may use Amazon trademarks in connection with the Program without prior approval, provided such use complies with Amazon''s publicly available brand guidelines. Amazon may request corrections for non-compliant uses.', ARRAY['may use','without prior approval','publicly available','brand guidelines','request corrections','non-compliant']::text[], '{"doc": "Counterparty_Proposal", "section": "Trademarks", "note": "Self-policing guideline compliance", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Self-policing compliance with brand guidelines eliminates Amazon''s prior approval control. Request for corrections after the fact is inadequate protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s prior approval is required for trademark use, which approval shall not be unreasonably withheld. Approval shall be deemed granted if Amazon fails to respond within five (5) business days of ProdCo''s request.', ARRAY['prior approval','not unreasonably withheld','deemed granted','fails to respond','five business days']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Short deemed approval window", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Five-day deemed approval is too short for proper trademark review, and ''not unreasonably withheld'' undermines Amazon''s discretion. Creates unacceptable trademark exposure."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Prior written approval is required for Amazon marks. Amazon hereby grants ProdCo a perpetual, irrevocable, royalty-free license to use Amazon marks in connection with the Program and any derivative works, spinoffs or franchises based thereon.', ARRAY['prior written approval','grants','perpetual','irrevocable','royalty-free license','Program','derivative works','spinoffs','franchises']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Perpetual irrevocable license", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Perpetual, irrevocable trademark license eliminates Amazon''s ongoing control over its marks. Amazon must retain ability to revoke trademark permissions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s approval is required for use of Amazon marks. In connection with any approved use, Amazon shall reimburse ProdCo for costs incurred in implementing Amazon''s brand requirements, including costs of producing materials featuring Amazon marks.', ARRAY['approval required','approved use','reimburse','costs','brand requirements','producing materials']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Cost reimbursement for brand compliance", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Requiring Amazon to reimburse costs of trademark use inverts the relationship. ProdCo should bear costs of using Amazon marks for its benefit."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Use of Amazon marks requires approval. If Amazon revokes any previously granted approval, Amazon shall provide ProdCo ninety (90) days'' notice and shall reimburse ProdCo for any non-recoverable costs incurred in reliance on such approval.', ARRAY['requires approval','revokes','ninety days notice','reimburse','non-recoverable costs','reliance']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Revocation limitations", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Extended notice period and reimbursement for revocation significantly limits Amazon''s ability to protect its marks. Amazon needs unfettered revocation right."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s approval is required for use of Amazon trademarks. Amazon grants ProdCo a co-exclusive license to use Amazon marks in connection with the Program, and Amazon shall not license any third party to use such marks in connection with the Program without ProdCo''s consent.', ARRAY['approval required','co-exclusive license','Amazon marks','Program','not license','third party','ProdCo consent']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Co-exclusive trademark license", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Co-exclusive license with restriction on Amazon''s ability to license its own marks to others is completely unacceptable. Amazon must retain full control over its trademarks."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Prior approval required for Amazon marks. ProdCo shall have the right to create and register Program-specific marks that incorporate Amazon trademarks (e.g., ''Amazon''s [Program Title]''), with ownership of such combined marks to be jointly held by Amazon and ProdCo.', ARRAY['prior approval','right to create','register','Program-specific marks','incorporate','joint ownership','combined marks']::text[], '{"doc": "Counterparty_Markup", "section": "Trademarks", "note": "Joint ownership of combined marks", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Joint ownership of marks incorporating Amazon trademarks is completely unacceptable. Amazon must be sole owner of all marks featuring Amazon branding."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain in strict confidence and shall not disclose to any third party any Non-Public Information (''NPI'') of Amazon, including without limitation the terms of this Agreement, information about the Program, Amazon''s business plans, strategies, financial information, technology, and any other information designated as confidential by Amazon.', ARRAY['strict confidence','not disclose','third party','NPI','Non-Public Information','terms of Agreement','Program','business plans','strategies','financial','technology','designated confidential']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Standard NPI obligation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard comprehensive NPI protection covering Agreement terms, Program information, and business information. Designation language provides flexibility for identifying additional NPI."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All Non-Public Information disclosed by Amazon to ProdCo, or otherwise obtained by ProdCo in connection with this Agreement, shall be held in strict confidence. ProdCo shall use NPI solely for the purpose of performing its obligations hereunder and for no other purpose.', ARRAY['Non-Public Information','disclosed','obtained','strict confidence','use solely','performing obligations','no other purpose']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Use limitation included", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes both confidentiality and use limitation, ensuring NPI is protected and used only for Agreement purposes. Essential dual protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo acknowledges that the existence and terms of this Agreement, all information relating to the Program (including scripts, treatments, casting, creative elements, release plans and marketing strategies), and all Amazon business information constitute NPI. ProdCo shall protect such NPI using at least the same degree of care it uses to protect its own confidential information, but in no event less than reasonable care.', ARRAY['existence terms Agreement','Program information','scripts','treatments','casting','creative','release plans','marketing','business information','NPI','same degree of care','reasonable care']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Enumerated NPI with care standard", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific categories of NPI and establishes care standard with reasonable care floor. Comprehensive and clear."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall keep confidential all NPI and shall not, without Amazon''s prior written consent, disclose NPI to any person or entity, or use NPI for any purpose other than as expressly authorized by this Agreement. This obligation shall survive termination or expiration of this Agreement indefinitely.', ARRAY['keep confidential','NPI','prior written consent','not disclose','any person entity','not use','except authorized','survive termination','indefinitely']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Indefinite survival", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Indefinite survival of confidentiality obligation ensures protection extends beyond Agreement term. Standard and appropriate for entertainment industry NPI."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall treat as strictly confidential all NPI, including any information that Amazon identifies as confidential or that ProdCo should reasonably understand to be confidential given its nature or the circumstances of disclosure. ProdCo shall implement appropriate administrative, technical and physical safeguards to protect NPI.', ARRAY['strictly confidential','NPI','identifies as confidential','reasonably understand','nature','circumstances','administrative','technical','physical safeguards']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Includes safeguards requirement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes objective ''reasonably understand'' standard and requires implementation of safeguards, providing robust protection mechanism."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain the confidentiality of all NPI and shall be responsible for any breach of this confidentiality obligation by its employees, contractors, agents or representatives. ProdCo shall ensure that all such persons are bound by confidentiality obligations no less protective than those set forth herein.', ARRAY['maintain confidentiality','NPI','responsible','breach','employees','contractors','agents','representatives','bound by','no less protective']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Extends to ProdCo personnel", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Makes ProdCo responsible for personnel breaches and requires binding personnel to equivalent confidentiality obligations. Essential for practical enforcement."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All NPI shall be and remain the exclusive property of Amazon. ProdCo''s confidentiality obligations hereunder shall apply to all NPI regardless of the form in which it is disclosed (oral, written, electronic or otherwise) and regardless of whether it is marked or identified as confidential at the time of disclosure.', ARRAY['NPI','exclusive property','Amazon','confidentiality obligations','regardless of form','oral','written','electronic','regardless','marked','identified']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Form-agnostic protection", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Protects NPI regardless of disclosure form and without requiring marking, eliminating potential loopholes based on formalities."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain the confidentiality of all NPI. Notwithstanding the foregoing, information shall not be considered NPI to the extent it: (a) is or becomes publicly available through no fault of ProdCo; (b) was rightfully in ProdCo''s possession prior to disclosure; or (c) is independently developed by ProdCo without use of NPI.', ARRAY['maintain confidentiality','NPI','notwithstanding','not considered NPI','publicly available','no fault','prior possession','independently developed','without use']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Standard confidentiality exceptions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard confidentiality exceptions (public domain, prior possession, independent development) are industry-standard and generally acceptable. Legal should confirm formulation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall keep all NPI strictly confidential. For purposes of this Agreement, ''NPI'' means information that is (a) designated as confidential by Amazon in writing, or (b) would reasonably be understood to be confidential given its nature, excluding information that is publicly available or independently known to ProdCo.', ARRAY['strictly confidential','NPI means','designated','writing','reasonably understood','nature','excluding','publicly available','independently known']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "NPI definition with exclusions", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Written designation requirement for some NPI may be acceptable if paired with ''reasonably understood'' standard. Legal should confirm public availability exclusion is properly scoped."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain the confidentiality of NPI for a period of five (5) years following disclosure. After such period, ProdCo''s confidentiality obligations shall terminate except with respect to trade secrets, which shall remain confidential indefinitely.', ARRAY['maintain confidentiality','NPI','five years','following disclosure','terminate','except','trade secrets','indefinitely']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Time-limited confidentiality with trade secret carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Five-year term with trade secret exception may be acceptable for general business information but Legal should confirm Program-related NPI is protected (ideally indefinitely)."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall protect NPI with at least the same level of care it applies to its own confidential information. Upon Amazon''s request, ProdCo shall provide reasonable evidence of its confidentiality safeguards, including security policies and access controls.', ARRAY['protect NPI','same level of care','own confidential information','upon request','reasonable evidence','safeguards','security policies','access controls']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Evidence of safeguards upon request", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Right to request evidence of safeguards is helpful for Amazon but may be viewed as additional burden by ProdCo. Requires Legal confirmation this is mutual benefit."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain the confidentiality of NPI. In the event of any actual or suspected breach of this confidentiality obligation, ProdCo shall immediately notify Amazon in writing and cooperate fully with Amazon''s investigation and remediation efforts.', ARRAY['maintain confidentiality','NPI','actual','suspected breach','immediately notify','writing','cooperate','investigation','remediation']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Breach notification and cooperation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Breach notification and cooperation requirements strengthen Amazon''s ability to respond to confidentiality incidents. Standard data protection practice."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Each party shall maintain the confidentiality of the other party''s confidential information. Amazon''s NPI includes Agreement terms, Program information, and business information. ProdCo''s confidential information includes its personnel information and proprietary production methodologies.', ARRAY['each party','other party''s','confidential information','Amazon NPI','Agreement','Program','business','ProdCo confidential','personnel','production methodologies']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Mutual confidentiality", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Mutual confidentiality is commonly requested by ProdCo. Acceptable if scope of Amazon''s obligations is limited and doesn''t restrict Amazon''s use of Materials or Program information."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain the confidentiality of NPI that is disclosed in writing and marked ''CONFIDENTIAL'' at the time of disclosure. Oral disclosures shall not be considered NPI unless confirmed in writing within thirty (30) days.', ARRAY['maintain confidentiality','NPI','disclosed in writing','marked CONFIDENTIAL','oral disclosures','not NPI','confirmed in writing','thirty days']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Marking and confirmation requirements", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Requiring written marking and confirmation creates significant gaps in protection. Program discussions, creative conversations, and business meetings generate NPI that may not be formally documented."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall use reasonable efforts to maintain the confidentiality of NPI. ProdCo shall not be liable for any disclosure of NPI that occurs despite ProdCo''s reasonable efforts to prevent such disclosure.', ARRAY['reasonable efforts','maintain confidentiality','NPI','not liable','disclosure','despite reasonable efforts']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Reasonable efforts with liability cap", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Reasonable efforts'' with liability exclusion for failed efforts essentially eliminates accountability for NPI breaches. ProdCo must be strictly liable for breaches regardless of effort."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain the confidentiality of NPI for a period of one (1) year following the initial release of the Program. After such date, all NPI shall be deemed non-confidential.', ARRAY['maintain confidentiality','NPI','one year','initial release','deemed non-confidential']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "One-year post-release limit", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "One-year post-release confidentiality is wholly inadequate. Business strategies, financial terms, and future plans remain sensitive indefinitely. This limitation is unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain the confidentiality of NPI, except that ProdCo may disclose NPI to potential investors, lenders, or acquirers in connection with financing or sale transactions involving ProdCo, provided such recipients agree to keep the information confidential.', ARRAY['maintain confidentiality','NPI','except','disclose','investors','lenders','acquirers','financing','sale transactions','recipients','confidential']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "M&A and financing carveout", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Broad carveout for investors, lenders, and acquirers without Amazon approval creates uncontrolled disclosure risk. Amazon NPI could be shared with competitors or leaked through transaction processes."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain the confidentiality of NPI. Notwithstanding the foregoing, the financial terms of this Agreement shall not be considered NPI and may be disclosed by ProdCo to third parties.', ARRAY['maintain confidentiality','NPI','notwithstanding','financial terms','not NPI','may be disclosed','third parties']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Financial terms excluded from NPI", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding financial terms from NPI allows ProdCo to disclose deal terms publicly or to competitors. Financial terms are core NPI that must be protected."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The parties shall maintain the confidentiality of each other''s NPI on a mutual and equivalent basis. Neither party shall have greater confidentiality obligations than the other, and any confidentiality protection afforded to Amazon''s NPI shall equally apply to ProdCo''s confidential information.', ARRAY['mutual','equivalent basis','neither party','greater obligations','confidentiality protection','equally apply']::text[], '{"doc": "Counterparty_Proposal", "section": "Confidentiality", "note": "Forced mutuality and equivalence", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Forced equivalence ignores asymmetry of information flows. Amazon discloses far more valuable NPI than ProdCo. Mutual obligations are acceptable but cannot be forced to equivalence."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall maintain the confidentiality of NPI. In the event of any breach of confidentiality by ProdCo, Amazon''s sole remedy shall be injunctive relief, and ProdCo shall not be liable for any monetary damages resulting from such breach.', ARRAY['maintain confidentiality','NPI','breach','sole remedy','injunctive relief','not liable','monetary damages']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "No monetary damages for breach", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting remedies to injunctive relief only eliminates accountability for NPI breaches. Amazon must have full remedies including monetary damages for confidentiality violations."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI to its employees, contractors and professional advisors who have a need to know such information for purposes of performing ProdCo''s obligations under this Agreement, provided such persons are bound by confidentiality obligations at least as protective as those set forth herein.', ARRAY['may disclose','NPI','employees','contractors','professional advisors','need to know','performing obligations','bound by','confidentiality obligations','as protective']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Standard need-to-know exception", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard need-to-know exception limited to persons performing Agreement obligations, with requirement for binding confidentiality. Appropriate and necessary for practical performance."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding the confidentiality obligations above, ProdCo may disclose NPI to: (a) ProdCo''s employees with a bona fide need to know; (b) ProdCo''s legal counsel and accountants; and (c) contractors engaged in connection with the Program, in each case subject to binding confidentiality obligations no less restrictive than this Agreement.', ARRAY['notwithstanding','may disclose','NPI','employees','bona fide need to know','legal counsel','accountants','contractors','Program','binding confidentiality','no less restrictive']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Enumerated permitted recipients", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific categories of permitted recipients with appropriate confidentiality binding requirement. Clear and appropriately limited."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo may share NPI with its affiliates, employees and contractors on a need-to-know basis for purposes of this Agreement, provided that ProdCo shall remain fully responsible for any breach of confidentiality by such persons and shall ensure they are bound by appropriate confidentiality obligations prior to any disclosure.', ARRAY['may share','NPI','affiliates','employees','contractors','need-to-know','purposes','remain responsible','breach','ensure bound','prior to disclosure']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "ProdCo responsibility for recipients", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Expressly preserves ProdCo''s responsibility for recipient breaches and requires pre-disclosure binding. Strong protective language within permitted disclosure."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI to cast, crew and production personnel as necessary for production of the Program, provided such persons execute confidentiality agreements in a form approved by Amazon or containing terms substantially similar to those in Amazon''s standard confidentiality agreement.', ARRAY['may disclose','NPI','cast','crew','production personnel','necessary','production','execute confidentiality agreements','approved by Amazon','substantially similar']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Production personnel with approved NDAs", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Addresses practical need to share NPI with production personnel while requiring Amazon-approved or equivalent NDAs. Appropriate for production context."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Disclosure of NPI is permitted to ProdCo''s professional advisors (legal, accounting, tax) who are subject to professional duties of confidentiality, and to ProdCo''s employees and contractors who need the information to perform services for the Program and who have executed Amazon''s standard NDA or equivalent.', ARRAY['disclosure permitted','professional advisors','legal','accounting','tax','professional duties','employees','contractors','need information','executed NDA','equivalent']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Professional duty recognition", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Recognizes that professional advisors are bound by professional duties, while still requiring executed NDAs for employees and contractors."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI to permitted recipients who have a need to know, subject to confidentiality binding. For the avoidance of doubt, ''need to know'' means a genuine business need directly related to performing obligations under this Agreement, and not mere curiosity or general business interest.', ARRAY['may disclose','NPI','permitted recipients','need to know','confidentiality binding','genuine business need','directly related','performing obligations','not curiosity','general business interest']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Need-to-know definition", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Defines ''need to know'' to prevent over-broad interpretation. Clarifies that casual interest doesn''t qualify, limiting disclosure scope."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Permitted disclosures to need-to-know recipients shall be limited to the minimum amount of NPI necessary for the relevant purpose. ProdCo shall not disclose the complete Agreement or comprehensive Program information when a summary or excerpt would suffice.', ARRAY['permitted disclosures','need-to-know','limited','minimum amount','NPI','necessary','relevant purpose','not disclose','complete Agreement','summary','excerpt']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Minimum necessary principle", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Minimum necessary principle further limits disclosure even to permitted recipients. Prevents wholesale sharing when targeted disclosure would suffice."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may disclose NPI to its parent company and wholly-owned subsidiaries on a need-to-know basis, provided such affiliates are bound by confidentiality obligations. ProdCo shall provide Amazon with a list of affiliates to whom NPI has been disclosed upon Amazon''s reasonable request.', ARRAY['may disclose','NPI','parent company','wholly-owned subsidiaries','need-to-know','affiliates','bound','confidentiality','provide list','upon request']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Affiliate disclosure with list upon request", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Affiliate disclosure with list-upon-request provides transparency. Legal should confirm ''wholly-owned'' limitation is maintained and parent company disclosure is acceptable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may disclose NPI to its employees and contractors who need to know, provided that before any such disclosure, ProdCo shall: (a) inform such persons of the confidential nature of the NPI; (b) obtain their written agreement to protect such NPI; and (c) maintain records of such disclosures for Amazon''s audit purposes.', ARRAY['may disclose','NPI','employees','contractors','need to know','before disclosure','inform','confidential nature','written agreement','maintain records','audit purposes']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Disclosure records for audit", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Record-keeping for audit purposes provides Amazon visibility into NPI disclosures. May be helpful for compliance monitoring. Requires Legal confirmation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may share NPI with need-to-know recipients. In addition, ProdCo may disclose general, non-specific information about its relationship with Amazon (e.g., that ProdCo is producing a series for a major streaming platform) without identifying Amazon by name, for ProdCo''s general business development purposes.', ARRAY['may share','NPI','need-to-know','general non-specific','relationship','without identifying Amazon','business development']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Anonymized general disclosure", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Anonymized general disclosure for business development may be acceptable if truly non-identifying. Legal should assess whether ''major streaming platform'' language is sufficiently anonymized in context."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may disclose NPI to its attorneys, accountants, and bankers in connection with legal, financial, and lending matters, provided such advisors are bound by professional duties of confidentiality or have executed appropriate NDAs, and provided further that ProdCo shall not disclose more information than reasonably necessary.', ARRAY['may disclose','NPI','attorneys','accountants','bankers','legal','financial','lending','professional duties','NDAs','not disclose more','reasonably necessary']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Bankers added to advisors", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Adding bankers for lending matters is reasonable business need but expands disclosure beyond typical professional advisors. Legal should confirm scope is appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'NPI may be disclosed to guild and union representatives to the extent required by applicable collective bargaining agreements. ProdCo shall use reasonable efforts to limit such disclosures to information actually required and to obtain confidential treatment where possible.', ARRAY['NPI','disclosed','guild','union representatives','required','collective bargaining agreements','limit disclosures','actually required','confidential treatment']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Guild/union disclosure carveout", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Guild/union disclosure may be required by CBA obligations. Limitation to required information and confidential treatment efforts provide protection. Legal should confirm CBA obligations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may disclose NPI to its employees and contractors on a need-to-know basis. If any such employee or contractor''s engagement terminates, ProdCo shall take reasonable steps to ensure the return or destruction of any NPI in such person''s possession.', ARRAY['may disclose','NPI','employees','contractors','need-to-know','engagement terminates','reasonable steps','return','destruction','possession']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Return/destruction on termination", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Return/destruction requirement upon personnel termination is good practice that enhances protection. Requires Legal confirmation this is operationally enforceable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI to any person or entity that ProdCo reasonably believes has a need to receive such information, provided ProdCo uses reasonable efforts to bind such recipients to confidentiality.', ARRAY['may disclose','NPI','any person entity','reasonably believes','need to receive','reasonable efforts','bind','confidentiality']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Unlimited discretion on recipients", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Unlimited ProdCo discretion to determine recipients based on ''reasonable belief'' and only ''reasonable efforts'' to bind is far too broad. Amazon has no control over NPI distribution."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI to its employees, contractors, advisors, affiliates, investors, prospective investors, acquirers, prospective acquirers, and business partners, in each case on a need-to-know basis and subject to confidentiality obligations.', ARRAY['may disclose','NPI','employees','contractors','advisors','affiliates','investors','prospective investors','acquirers','prospective acquirers','business partners','need-to-know','confidentiality']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Overly broad recipient list", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Including investors, prospective investors, acquirers, and ''business partners'' in permitted recipients is far too broad. M&A and investment disclosures require Amazon''s specific approval."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI to need-to-know recipients. ProdCo shall not be required to execute confidentiality agreements with such recipients if ProdCo reasonably believes such recipients will maintain confidentiality based on the nature of their relationship with ProdCo.', ARRAY['may disclose','NPI','need-to-know','not required','confidentiality agreements','reasonably believes','maintain confidentiality','relationship']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "No binding requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Eliminating requirement to bind recipients to confidentiality based on ProdCo''s ''reasonable belief'' provides no enforceable protection. All recipients must be bound by confidentiality obligations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI to its entire workforce on a company-wide basis, as ProdCo believes that transparency with employees enhances morale and productivity. ProdCo shall include confidentiality reminders in its employee handbook.', ARRAY['may disclose','NPI','entire workforce','company-wide','transparency','employees','morale','productivity','confidentiality reminders','handbook']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Company-wide disclosure", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Company-wide disclosure with only handbook reminders is completely unacceptable. NPI must be limited to need-to-know personnel with binding confidentiality obligations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may share NPI with need-to-know recipients. Any breach of confidentiality by such recipients shall be the responsibility of the recipient, not ProdCo, and Amazon shall pursue remedies directly against the breaching party.', ARRAY['may share','NPI','need-to-know','breach','responsibility of recipient','not ProdCo','pursue remedies','directly','breaching party']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "ProdCo not responsible for recipient breaches", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Releasing ProdCo from responsibility for recipient breaches eliminates accountability for NPI protection. ProdCo must remain responsible for all disclosures it makes."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI to co-producers, co-financiers, completion bond companies, errors and omissions insurers, and distribution partners in connection with the production and distribution of the Program, without Amazon''s prior approval.', ARRAY['may disclose','NPI','co-producers','co-financiers','completion bond','E&O insurers','distribution partners','without Amazon approval']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Industry partners without approval", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Disclosure to co-producers, financiers, and distribution partners without Amazon approval creates uncontrolled NPI dissemination. These disclosures require Amazon''s specific consent."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If ProdCo is required by law, regulation, court order or governmental authority to disclose any NPI, ProdCo shall, to the extent legally permitted, provide Amazon with prompt written notice of such requirement prior to disclosure, and shall cooperate with Amazon in seeking protective treatment for such NPI.', ARRAY['required by law','regulation','court order','governmental authority','disclose NPI','legally permitted','prompt written notice','prior to disclosure','cooperate','protective treatment']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Standard compelled disclosure provision", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard provision requiring advance notice where legally permitted and cooperation in seeking protective orders. Provides Amazon opportunity to protect NPI in legal proceedings."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If ProdCo receives a subpoena, court order, or other legal process requiring disclosure of NPI, ProdCo shall: (a) notify Amazon immediately and in any event within two (2) business days; (b) provide Amazon copies of the relevant demand; (c) cooperate with any effort by Amazon to obtain protective orders; and (d) disclose only such NPI as is legally required.', ARRAY['subpoena','court order','legal process','notify Amazon','immediately','two business days','copies of demand','cooperate','protective orders','disclose only','legally required']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Detailed compelled disclosure process", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Detailed procedural requirements including specific timing, document sharing, and minimum-disclosure principle. Comprehensive protection for compelled disclosure scenarios."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Compelled disclosure of NPI pursuant to legal process shall not constitute a breach of this Agreement, provided that ProdCo: (i) gives Amazon prompt advance notice to the extent not prohibited by law; (ii) reasonably cooperates with Amazon''s efforts to limit or prevent disclosure; and (iii) limits disclosure to what is strictly required.', ARRAY['compelled disclosure','legal process','not breach','prompt advance notice','not prohibited','reasonably cooperates','limit prevent disclosure','strictly required']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Not-a-breach framing with conditions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarifies compelled disclosure is not a breach while imposing protective conditions. Appropriate balance between legal compliance and NPI protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI if required by applicable law, regulation, or valid legal process. Prior to any such disclosure, ProdCo shall provide Amazon with sufficient notice to allow Amazon to seek a protective order or other appropriate remedy, and ProdCo shall cooperate fully with such efforts at Amazon''s expense.', ARRAY['may disclose','NPI','required by law','regulation','legal process','prior to disclosure','sufficient notice','protective order','appropriate remedy','cooperate fully','Amazon''s expense']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Cooperation at Amazon expense", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Places cooperation costs on Amazon, which is reasonable since Amazon is the beneficiary of protective efforts. Otherwise standard compelled disclosure language."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If legally compelled to disclose NPI, ProdCo shall provide Amazon notice within twenty-four (24) hours of receiving such legal demand, unless prohibited by law. ProdCo shall assert all available privileges and protections and shall not waive any such protections without Amazon''s written consent.', ARRAY['legally compelled','disclose NPI','notice','twenty-four hours','unless prohibited','assert privileges','protections','not waive','written consent']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "24-hour notice with privilege protection", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Tight 24-hour notice window and requirement to assert privileges without waiver provides strong protection. Appropriate for high-sensitivity NPI."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding the confidentiality obligations herein, ProdCo may disclose NPI to the extent required by law, provided that: (a) ProdCo provides Amazon maximum possible notice; (b) ProdCo limits disclosure to the minimum required; (c) ProdCo seeks confidential treatment; and (d) ProdCo coordinates with Amazon on the disclosure.', ARRAY['notwithstanding','may disclose','required by law','maximum possible notice','minimum required','confidential treatment','coordinates with Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Four-prong protection", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Four protective requirements (notice, minimum disclosure, confidential treatment, coordination) provide comprehensive safeguards for compelled disclosure."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If ProdCo is required to disclose NPI in connection with securities filings, regulatory requirements, or governmental investigations, ProdCo shall notify Amazon promptly and shall work with Amazon to limit such disclosure and obtain confidential treatment under applicable rules.', ARRAY['required to disclose','NPI','securities filings','regulatory requirements','governmental investigations','notify promptly','work with Amazon','limit disclosure','confidential treatment']::text[], '{"doc": "PSA_Principal_Terms", "section": "Confidentiality", "note": "Securities and regulatory context", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Addresses specific securities and regulatory disclosure contexts with appropriate notice and limitation requirements."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may disclose NPI if required by law, regulation, or court order, provided that ProdCo gives Amazon notice as soon as reasonably practicable and cooperates with protective efforts. If ProdCo is prohibited by law from providing advance notice, ProdCo shall notify Amazon promptly after such prohibition expires.', ARRAY['may disclose','NPI','required by law','court order','notice','reasonably practicable','cooperates','prohibited','advance notice','notify after','prohibition expires']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Post-prohibition notice", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Post-prohibition notice requirement is reasonable addition that ensures Amazon learns of disclosure even when advance notice was prohibited. Requires Legal confirmation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If compelled to disclose NPI, ProdCo shall notify Amazon promptly. ProdCo shall not be required to take any action that would expose ProdCo to sanctions for contempt of court or violation of law, but shall use commercially reasonable efforts to enable Amazon to seek protective treatment.', ARRAY['compelled','disclose NPI','notify promptly','not required','contempt of court','violation of law','commercially reasonable efforts','protective treatment']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Contempt protection", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Contempt/violation protection is reasonable practical limitation. ProdCo should not be required to violate court orders. Requires Legal confirmation of scope."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may disclose NPI if legally required, with prompt notice to Amazon. If Amazon wishes to challenge the disclosure requirement, Amazon shall bear all costs and expenses of such challenge, and ProdCo shall cooperate as reasonably requested.', ARRAY['may disclose','NPI','legally required','prompt notice','Amazon challenge','bear costs expenses','ProdCo cooperate','reasonably requested']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Amazon bears challenge costs", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Placing challenge costs on Amazon is reasonable since Amazon benefits from protective efforts. Reasonable cooperation standard is appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Compelled disclosures of NPI shall be permitted with prompt notice to Amazon. For disclosures required by routine securities filings (10-K, 10-Q, proxy statements), ProdCo shall notify Amazon at least ten (10) business days in advance of the filing deadline to allow review and comment.', ARRAY['compelled disclosures','NPI','prompt notice','securities filings','10-K','10-Q','proxy','ten business days','advance','filing deadline','review comment']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Securities filing advance notice", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Ten-day advance notice for routine securities filings provides Amazon opportunity to review and seek confidential treatment. Requires Legal confirmation this is operationally workable."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may disclose NPI as required by law. If Amazon disputes that disclosure is legally required, the parties shall promptly meet and confer. If the dispute is not resolved within three (3) business days, ProdCo may proceed with disclosure as it reasonably determines is required.', ARRAY['may disclose','NPI','required by law','Amazon disputes','meet and confer','three business days','not resolved','proceed with disclosure','reasonably determines']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Meet-and-confer with resolution timeline", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Meet-and-confer process with defined timeline provides structure for disputes. Three-day resolution period may be tight. Requires Legal assessment."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If legally compelled to disclose NPI, ProdCo shall notify Amazon and disclose only the minimum NPI required. Both parties acknowledge that applicable law may require disclosure of certain information (e.g., material contracts for SEC filings) and agree to work together in good faith to address such requirements.', ARRAY['legally compelled','disclose NPI','notify','minimum NPI','applicable law','material contracts','SEC filings','work together','good faith']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "SEC material contract acknowledgment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Acknowledges SEC material contract disclosure requirements which may be applicable. Good faith cooperation commitment is reasonable. Requires Legal confirmation of SEC treatment."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI if required by law, regulation, or legal process. ProdCo shall use reasonable efforts to notify Amazon of such disclosure but shall not be required to delay disclosure or seek protective treatment.', ARRAY['may disclose','NPI','required by law','reasonable efforts','notify','not required','delay disclosure','seek protective treatment']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "No delay or protective treatment requirement", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Eliminating requirements to delay disclosure and seek protective treatment provides no meaningful opportunity for Amazon to protect NPI. These protective measures are essential."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI to the extent ProdCo reasonably believes such disclosure is required by applicable law or regulation. ProdCo shall not be required to provide advance notice to Amazon of any such disclosure.', ARRAY['may disclose','NPI','reasonably believes','required by law','not required','advance notice']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Subjective legal requirement, no notice", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Subjective ''reasonably believes'' standard without notice requirement gives ProdCo unfettered discretion to disclose NPI without any opportunity for Amazon to object or seek protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI as required by law. Notwithstanding the foregoing, if Amazon does not respond to ProdCo''s notice of compelled disclosure within forty-eight (48) hours, ProdCo may proceed with full disclosure without limitation.', ARRAY['may disclose','NPI','required by law','Amazon does not respond','forty-eight hours','full disclosure','without limitation']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Short response window, unlimited disclosure", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "48-hour response window is too short for Amazon to obtain protective orders, and ''full disclosure without limitation'' exceeds what is legally required. Both elements are problematic."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI if required by law, court order, or government request. ProdCo shall also have the right to disclose NPI if ProdCo believes in good faith that such disclosure is necessary to protect ProdCo''s legal rights or business interests.', ARRAY['may disclose','NPI','required by law','court order','government request','right to disclose','good faith','protect legal rights','business interests']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Self-help legal/business disclosure", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Adding subjective ''business interests'' exception goes far beyond compelled disclosure. ProdCo could justify almost any disclosure as protecting its interests. Completely unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If compelled to disclose NPI by legal process, ProdCo shall notify Amazon. However, if the disclosure request is from a governmental authority in connection with an investigation, ProdCo may comply immediately without notice to Amazon to avoid obstructing such investigation.', ARRAY['compelled','disclose NPI','legal process','notify','governmental authority','investigation','comply immediately','without notice','avoid obstructing']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Government investigation exception", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Blanket exception for government investigations without notice allows ProdCo to disclose NPI without any Amazon awareness. Many investigation disclosures permit notice unless explicitly prohibited."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may disclose NPI as required by law. For purposes of this provision, ''required by law'' includes any disclosure that ProdCo''s legal counsel advises is required or advisable to comply with applicable law or regulation.', ARRAY['may disclose','NPI','required by law','includes','legal counsel advises','required or advisable','comply']::text[], '{"doc": "Counterparty_Markup", "section": "Confidentiality", "note": "Advisable disclosure included", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Expanding ''required by law'' to include ''advisable'' disclosures creates enormous loophole. Legal counsel could advise many disclosures as ''advisable'' that are not actually required."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not input, upload, transmit or otherwise provide any NPI, Program information, Materials, scripts, treatments, or any other confidential information into any artificial intelligence tool, machine learning system, large language model, or similar technology, whether or not such technology is publicly available, without Amazon''s prior written approval.', ARRAY['not input','upload','transmit','provide','NPI','Program information','Materials','scripts','treatments','confidential','artificial intelligence','machine learning','large language model','prior written approval']::text[], '{"doc": "PSA_Principal_Terms", "section": "AI Restrictions", "note": "Comprehensive AI input prohibition", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive prohibition on inputting any Amazon confidential information into AI tools. Covers all forms of AI technology and requires prior written approval for any exception. Post-2023 critical provision."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo and its personnel shall not use any generative AI tool, including without limitation ChatGPT, Claude, Gemini, Midjourney, DALL-E, or any similar technology, in connection with the Program or to process any NPI, Materials, or Amazon confidential information. This prohibition applies regardless of whether the AI tool retains or trains on inputted data.', ARRAY['not use','generative AI','ChatGPT','Claude','Gemini','Midjourney','DALL-E','Program','NPI','Materials','confidential','regardless','retains','trains']::text[], '{"doc": "PSA_Principal_Terms", "section": "AI Restrictions", "note": "Named tools prohibition", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Names specific AI tools while including catch-all. Addresses both retention and training concerns. Extends to all ProdCo personnel. Comprehensive protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Without Amazon''s prior written consent, ProdCo shall not: (a) input any NPI, Program content, or Materials into any AI system; (b) use AI tools to generate any content for the Program; (c) use AI tools to analyze, summarize, or process any Amazon information; or (d) permit any third party to perform any of the foregoing.', ARRAY['without prior consent','not input','NPI','Program content','Materials','AI system','use AI','generate content','analyze','summarize','process','permit third party']::text[], '{"doc": "PSA_Principal_Terms", "section": "AI Restrictions", "note": "Enumerated prohibitions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerates specific prohibited uses including input, generation, analysis, and third-party activities. Comprehensive coverage of AI-related risks."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo acknowledges that AI tools may retain, train on, or otherwise process inputted data in ways that could compromise confidentiality. ProdCo therefore agrees not to input any NPI, Materials, or Program information into any AI tool and shall include equivalent restrictions in all agreements with its personnel and contractors.', ARRAY['acknowledges','AI tools','retain','train','process','compromise confidentiality','not input','NPI','Materials','Program','equivalent restrictions','personnel','contractors']::text[], '{"doc": "PSA_Principal_Terms", "section": "AI Restrictions", "note": "Acknowledgment with flow-down", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Includes acknowledgment of AI training risks and requires flow-down to personnel and contractors. Addresses practical enforcement concerns."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The AI restriction in this Agreement applies to all forms of artificial intelligence, including generative AI, predictive AI, machine learning models, neural networks, and any successor or similar technologies. ProdCo shall not input NPI or Program information into any such technology without Amazon''s express prior authorization.', ARRAY['AI restriction','all forms','generative AI','predictive AI','machine learning','neural networks','successor','similar technologies','not input','NPI','Program','express prior authorization']::text[], '{"doc": "PSA_Principal_Terms", "section": "AI Restrictions", "note": "Technology-agnostic AI definition", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Broad technology-agnostic definition ensures restriction covers current and future AI technologies. Prevents arguments based on narrow AI definitions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall implement reasonable technical and administrative controls to prevent unauthorized input of NPI or Program Materials into AI systems, including blocking access to public AI tools on production networks and providing training to personnel on this prohibition.', ARRAY['implement','technical','administrative controls','prevent','unauthorized input','NPI','Program Materials','AI systems','blocking access','public AI tools','training','personnel']::text[], '{"doc": "PSA_Principal_Terms", "section": "AI Restrictions", "note": "Controls and training requirement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Requires affirmative implementation of controls and training, going beyond mere prohibition to address practical compliance mechanisms."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'No NPI, Materials, scripts, or Program information shall be inputted into any AI tool. This restriction survives termination of this Agreement and applies in perpetuity. ProdCo shall be strictly liable for any breach of this provision by ProdCo or any of its personnel, contractors, or agents.', ARRAY['no NPI','Materials','scripts','Program','inputted','AI tool','survives termination','perpetuity','strictly liable','breach','personnel','contractors','agents']::text[], '{"doc": "PSA_Principal_Terms", "section": "AI Restrictions", "note": "Perpetual restriction with strict liability", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Perpetual survival appropriate given permanent nature of AI training data. Strict liability ensures accountability regardless of intent or negligence level."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall not input NPI or Program Materials into any AI tool without Amazon''s prior written approval. Notwithstanding the foregoing, ProdCo may use AI tools that have been expressly approved by Amazon in writing, subject to any conditions specified in such approval.', ARRAY['not input','NPI','Program Materials','AI tool','prior written approval','notwithstanding','expressly approved','writing','conditions specified']::text[], '{"doc": "PSA_Fallbacks", "section": "AI Restrictions", "note": "Approved tools exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Allows for approved-tools exception which may be necessary for certain production workflows. Approval must be express, written, and conditional. Requires Legal approval."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall not input NPI or Materials into public AI tools. ProdCo may use enterprise AI solutions that are deployed on-premises or in a private cloud environment and that do not transmit data externally, provided ProdCo notifies Amazon in advance and such solutions meet Amazon''s security requirements.', ARRAY['not input','NPI','Materials','public AI tools','enterprise AI','on-premises','private cloud','do not transmit externally','notifies Amazon','advance','security requirements']::text[], '{"doc": "PSA_Fallbacks", "section": "AI Restrictions", "note": "Enterprise/private AI exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Private/enterprise AI exception with security requirements may be acceptable for sophisticated ProdCos. Requires advance notice and security compliance. Legal approval required."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall not input NPI or Program Materials into any AI tool without approval. If ProdCo wishes to use AI tools for administrative purposes unrelated to Program content (e.g., scheduling, budget tracking), ProdCo shall submit a request describing the proposed use, and Amazon shall not unreasonably withhold approval.', ARRAY['not input','NPI','Program Materials','AI tool','approval','administrative purposes','unrelated to Program','scheduling','budget tracking','submit request','not unreasonably withhold']::text[], '{"doc": "Counterparty_Markup", "section": "AI Restrictions", "note": "Administrative use exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Administrative-use exception for non-content purposes may be reasonable if truly divorced from NPI. ''Not unreasonably withhold'' provides Amazon flexibility. Requires Legal review."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall not input NPI, Materials, or Program content into AI tools. ProdCo shall include equivalent AI restrictions in all agreements with cast, crew, and production personnel. Upon Amazon''s request, ProdCo shall provide certification that such restrictions have been included.', ARRAY['not input','NPI','Materials','Program','AI tools','equivalent restrictions','cast','crew','production personnel','upon request','certification','included']::text[], '{"doc": "PSA_Fallbacks", "section": "AI Restrictions", "note": "Flow-down with certification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Flow-down requirement with certification mechanism ensures AI restrictions extend to all production personnel. Certification provides verification. Requires Legal confirmation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall not use AI tools to process NPI or generate Program content. If ProdCo inadvertently inputs NPI into an AI tool, ProdCo shall immediately notify Amazon, take all available steps to delete such data from the AI system, and provide Amazon a detailed incident report within forty-eight (48) hours.', ARRAY['not use','AI tools','process NPI','generate Program content','inadvertently inputs','immediately notify','delete data','AI system','incident report','forty-eight hours']::text[], '{"doc": "Counterparty_Markup", "section": "AI Restrictions", "note": "Incident response procedure", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Incident response procedure for inadvertent inputs is practical addition. Deletion and reporting requirements are appropriate. Requires Legal confirmation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo agrees to comply with Amazon''s AI Usage Policy as provided by Amazon from time to time. ProdCo shall not input NPI or Materials into any AI tool except as expressly permitted by such policy. ProdCo acknowledges receipt of the current version of such policy.', ARRAY['comply','Amazon''s AI Usage Policy','from time to time','not input','NPI','Materials','except as permitted','policy','acknowledges receipt','current version']::text[], '{"doc": "PSA_Fallbacks", "section": "AI Restrictions", "note": "Reference to Amazon AI policy", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Reference to Amazon policy provides flexibility to update AI restrictions as technology evolves. Policy acknowledgment creates compliance baseline. Requires Legal review of policy terms."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall use reasonable efforts to prevent input of NPI into public AI tools. ProdCo shall not be liable for any inadvertent or unauthorized input of NPI into AI systems by its employees or contractors.', ARRAY['reasonable efforts','prevent input','NPI','public AI tools','not liable','inadvertent','unauthorized','employees','contractors']::text[], '{"doc": "Counterparty_Markup", "section": "AI Restrictions", "note": "Reasonable efforts with liability exclusion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "''Reasonable efforts'' standard with liability exclusion for employee/contractor actions is completely inadequate. ProdCo must be strictly liable for all AI input regardless of intent."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall not input NPI into public AI tools. ProdCo may use AI tools for creative development of the Program, including script drafting, character development, and plot analysis, provided any AI-generated content is reviewed and modified by human personnel before use.', ARRAY['not input','NPI','public AI tools','may use','creative development','script drafting','character development','plot analysis','AI-generated content','reviewed','modified','human']::text[], '{"doc": "Counterparty_Markup", "section": "AI Restrictions", "note": "Creative development AI exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Allowing AI for creative development (scripts, characters, plots) creates massive content and ownership risks. AI-generated content raises fundamental copyright and originality issues. Not acceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall not input NPI into AI tools that are known to retain or train on user data. ProdCo may use AI tools that contractually commit not to retain or use inputted data for training purposes.', ARRAY['not input','NPI','AI tools','known to retain','train on user data','may use','contractually commit','not retain','not use','training']::text[], '{"doc": "Counterparty_Markup", "section": "AI Restrictions", "note": "Non-training AI exception", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Distinction based on AI training practices is difficult to verify and evolves constantly. Contractual commitments by AI providers may not be enforceable or reliable. Creates unacceptable compliance uncertainty."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The AI restriction herein shall apply only during principal photography and post-production. After delivery of the Program, ProdCo shall be free to use AI tools to analyze and discuss the Program for portfolio, educational, and marketing purposes.', ARRAY['AI restriction','only during','principal photography','post-production','after delivery','free to use','AI tools','analyze','discuss','portfolio','educational','marketing']::text[], '{"doc": "Counterparty_Markup", "section": "AI Restrictions", "note": "Time-limited restriction", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Time-limited AI restriction fails to protect NPI and Materials in perpetuity. Post-delivery AI use for ''portfolio'' and ''marketing'' could expose Program content and trade secrets permanently."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall not input NPI into AI tools. Notwithstanding the foregoing, this restriction shall not apply to AI tools that are industry-standard in the entertainment production sector, as ProdCo determines in good faith.', ARRAY['not input','NPI','AI tools','notwithstanding','not apply','industry-standard','entertainment production','ProdCo determines','good faith']::text[], '{"doc": "Counterparty_Markup", "section": "AI Restrictions", "note": "Industry-standard exception", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo discretion to determine ''industry-standard'' AI tools eliminates meaningful restriction. The entertainment industry is rapidly adopting AI tools, making this exception effectively unlimited."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon acknowledges that AI tools are increasingly essential to modern production workflows. ProdCo may use AI tools as it deems appropriate in its professional judgment, provided ProdCo takes reasonable precautions to protect NPI confidentiality.', ARRAY['acknowledges','AI tools','essential','modern production','may use','deems appropriate','professional judgment','reasonable precautions','protect NPI']::text[], '{"doc": "Counterparty_Proposal", "section": "AI Restrictions", "note": "ProdCo discretion with precautions", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Complete ProdCo discretion with only ''reasonable precautions'' provides no meaningful protection. This essentially negates any AI restriction. Completely unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo shall not input NPI or Materials into AI tools without Amazon''s approval. Amazon shall approve or deny any such request within five (5) business days; failure to respond shall constitute approval. Amazon shall not unreasonably withhold approval for commonly-used AI productivity tools.', ARRAY['not input','NPI','Materials','AI tools','approval','approve or deny','five business days','failure to respond','constitute approval','not unreasonably withhold','productivity tools']::text[], '{"doc": "Counterparty_Markup", "section": "AI Restrictions", "note": "Deemed approval and reasonableness standard", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Deemed approval on non-response and ''not unreasonably withhold'' standard eliminate Amazon''s ability to control AI use. Given irreversible nature of AI training, Amazon must have absolute discretion."}'::jsonb)
