    AND m.code = 'third_party_credit'
    AND ct.code = 'third_party_credit_privity_reasonable_efforts_no_liability';

  IF mp_id IS NOT NULL AND ct_id IS NOT NULL THEN
    ON CONFLICT DO NOTHING;
  END IF;



